{
  "description": "The creature is shown in right-facing profile standing on a small patch of rocky ground. It has the overall body, fur, head, ears, eyes, snout and bushy tail of a large gray wolf, with thick shaggy gray, white and tan fur that is darker on the back and lighter on the chest and belly. Fused to its back and encircling its shoulders and lower neck are overlapping, spiky, dark brown chitinous plates like a crab's carapace. Two thin, segmented, brown antennae curve outward from the crown of its head between the ears. Its two hind legs are normal wolf legs ending in clawed canine paws, while its two front legs are fur-covered to the wrist and then terminate in large, mottled dark-brown crab pincers with black tips and small barnacle-like bumps, both pincers held just above the ground.",
  "parts": [
    {
      "part": "head",
      "looks_like": "wolf-like head with elongated snout, black nose, closed mouth, yellow-brown eyes, and gray-white fur with darker gray on top",
      "where": "at the far right front of the body, facing right"
    },
    {
      "part": "ears",
      "looks_like": "two upright, pointed, triangular wolf ears with dark interiors and gray fur",
      "where": "on top of the head, one in front of the other in profile"
    },
    {
      "part": "horns",
      "looks_like": "two thin, jointed, segmented, brownish antenna-like horns that curve outward and taper to a point",
      "where": "protruding from the crown of the head between and just in front of the ears"
    },
    {
      "part": "tentacles",
      "looks_like": "same two thin segmented antennae, tentacle-like and jointed",
      "where": "on the top of the head between the ears"
    },
    {
      "part": "mane",
      "looks_like": "thick, shaggy, long fur forming a ruff around the neck and chest, gray and white",
      "where": "around the neck, throat and chest extending back to the shoulders"
    },
    {
      "part": "legs",
      "looks_like": "four legs: two slender hind legs covered in short gray fur with canine angulation, and two thicker front legs covered in shaggy gray fur down to a spiny joint",
      "where": "hind legs at the rear under the hips, front legs at the front under the chest, all supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "hind feet are canine paws with dark claws and pads on the ground; front feet are large, heavy, mottled dark-brown crab claws/pincers with bumpy texture, small circular barnacle marks and black tips",
      "where": "hind paws on the rocky ground at the bottom left-center, front claws suspended just above the ground at the bottom right-center"
    },
    {
      "part": "tail",
      "looks_like": "long, bushy, fur-covered wolf tail, gray with darker tip and lighter underside, hair hanging down",
      "where": "at the rear left end of the body, extending down from the rump"
    },
    {
      "part": "shell",
      "looks_like": "dark brown, hard, chitinous crab-like shell material with ridges and spines",
      "where": "fused to the back and shoulders"
    },
    {
      "part": "plates",
      "looks_like": "overlapping segmented armored plates with spiky edges, dark brown with lighter edges, forming a dorsal row from mid-back to shoulders and a separate collar-like band around the lower neck/shoulder with pointed projections",
      "where": "along the spine on the back and encircling the front of the torso at the shoulder/neck junction"
    },
    {
      "part": "markings",
      "looks_like": "natural wolf fur coloration: dark gray on back and tail, medium gray on sides and legs, white-cream on chest, belly, muzzle and around eyes, with subtle darker striping on hind legs",
      "where": "over the entire fur-covered body"
    }
  ],
  "attached_objects": [],
  "animals": [
    "wolf",
    "crab"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 2,
  "tails": 1
}
